}
final manager = SubagentManager(
  parentSessionId: '',
  messaging: fabric,
  selfId: 'main',
  homeDir: bundle.homeDir,
  wakeProcess: bundle.wakeProcess,
  sink: bundle.registrySink,
  source: bundle.registrySource,
)..machineName = bundle.machineName;
