  replyAutoSpill: bundle.replyAutoSpill,
  deliverableArtifactSink: bundle.deliverableArtifactSink,
  deliverableArtifactSource: bundle.deliverableArtifactSource,
  childSessionFactory: bundle.childSessionFactory,
