group('gh-2098: compaction tuning reaches the child pass', () {
  // The child rides the REGISTERED window (1000): the legacy curve
  // (forWindow(1000): reserve 16384) fires at 83616; a ratio of 0.7
  // pins the line at 700. The fixture sits an estimate of ~66k with
  // an observed context of ~71k — between the two lines, so ONLY the
  // tuned policy fires.
  test(
    'ratio 0.7: observed 71100 fires the pass the legacy curve ignores',
    () async {
      final registry = ContextWindowRegistry();
      registry.publish(
        model: _model,
        window: 1000000 ~/ 1000 * 1000,
        source: ContextWindowSource.endpointReport,
      );
      final wiring = _Wiring(
        registry: registry,
        compactionTuning: const CompactionTuning(triggerRatio: 0.7),
        fatChars: 260000,
      );
      wiring.stream.rules.addAll({
        'tuned-pass': () => _toolTurn('c1'),
        'fat:': () =>
            _toolTurn('c2', input: 100, cacheRead: 71000, totalTokens: 100),
      });
      final result = await wiring.executor.runSpawn(
        item: const TaskItem(
          name: 'tuned',
          agent: 'worker',
          task: 'tuned-pass',
        ),
        index: 0,
        context: '',
      );
      expect(result.status, TaskSpawnStatus.completed);

      // The estimate channel alone cannot fire: every real request
      // estimate stays under the tuned line (700).
      for (final context in wiring.stream.contexts) {
        final estimate = estimateRequestTokens(
          context.messages,
          systemPrompt: context.systemPrompt,
          tools: context.tools ?? const [],
        );
        expect(
          estimate,
          lessThan(700),
          reason: 'the estimate channel must stay under the tuned '
              'trigger for this repro (got $estimate)',
        );
      }
      expect(
        wiring.stream.compactionCalls,
        greaterThanOrEqualTo(1),
        reason: 'the tuned ratio line must fire the child pass '
            '(observed 71100 > 0.7 × 100000)',
      );
    },
  );

  test('without tuning the same transcript does not compact (control)',
      () async {
    final registry = ContextWindowRegistry();
    registry.publish(
      model: _model,
      window: 100000,
      source: ContextWindowSource.endpointReport,
    );
    final wiring = _Wiring(registry: registry, fatChars: 260000);
    wiring.stream.rules.addAll({
      'tuned-pass': () => _toolTurn('c1'),
      'fat:': () =>
          _toolTurn('c2', input: 100, cacheRead: 71000, totalTokens: 100),
    });
    await wiring.executor.runSpawn(
      item: const TaskItem(
        name: 'untuned',
        agent: 'worker',
        task: 'tuned-pass',
      ),
      index: 0,
      context: '',
    );
    // Estimate ~66k and observed ~71k, both under the legacy line
    // (83616) — neither channel crosses.
    expect(wiring.stream.compactionCalls, 0);
  });
});

