  Future<ConfigSetResult> set(
    String key,
    String value, {
    ConfigScope? scope,
  }) async {
    final segments = _parseKey(key);
    if (value.trim().isEmpty) {
      throw ConfigException(
        'empty value for "$key" — removing a key is a manual file edit',
