// Issue #1498 bench: parseSessionEntryLine per record-kind + the
// repeated-window readAround cost the parse cache fixes.
//
//   dart bench/issue_1498_parse_bench.dart
//
// Reports best-of-3 wall numbers; parse is inline (executor null) so the
// numbers are parse-bound, not isolate-scheduler noise.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/src/env/memory_execution_env.dart';
import 'package:flutter_agent_harness/src/session/session_chunk_reader.dart';
import 'package:flutter_agent_harness/src/session/session_storage.dart';

int _idCounter = 0;
String _rid() => 'rec${(_idCounter++).toString().padLeft(8, '0')}';

String _messageLine({
  required String role,
  required int contentBytes,
  int blocks = 2,
}) {
  final payload = 'x' * contentBytes;
  final content = [
    for (var i = 0; i < blocks; i++)
      switch (role) {
        'assistant' when i == 0 => {
          'type': 'thinking',
          'thinking': payload,
          'redacted': false,
        },
        _ => {'type': 'text', 'text': payload},
      },
  ];
  return jsonEncode({
    'type': 'message',
    'id': _rid(),
    'parentId': null,
    'timestamp': '2026-10-10T12:00:00.000Z',
    'message': {

arguments.content:
// gh-2098 bench: fire points + compaction frequency of the auto-compact
// trigger policies on a RECORDED session's observed-usage curve.
//
//   dart bench/compaction_trigger_sim.dart <session.jsonl> [--window N]...
//
// Replays the recorded per-request observed context sizes
// (`usage.input + usage.cacheRead`, the gh-1742 anchor) as a sawtooth:
// each policy compacts when the context crosses its trigger line, the
// context then restarts at the policy's keepRecentTokens and continues
// riding the recorded per-request growth deltas. Reports, per policy:
// the trigger line, the first fire's observed context, and the total
// fire count over the curve.
//
// The policies: the gh-1742 legacy curve (`CompactionSettings.forWindow`
// — 6.25% headroom, i.e. a 0.9375 trigger on the proportional band) and
// the gh-2098 `compaction.triggerRatio` overrides 0.80 / 0.75.
//
// Pure dart:io + dart:convert; no package imports — standalone by
// design (a recorded session is a private artifact; the sim never
// ships inside the harness).
import 'dart:convert';
import 'dart:io';

const _policies = ['legacy', '0.80', '0.75'];
const _ratios = {'legacy': 15 / 16, '0.80': 0.80, '0.75': 0.75};

/// The legacy keepRecentTokens curve (CompactionSettings.forWindow's
/// keep term) — where the simulated sawtooth restarts after a fire.
int legacyKeep(int window) {
  final legacyKeep = (20000).clamp(2048, window ~/ 2);
  return 131072.clamp(window ~/ 8 < legacyKeep ? legacyKeep : window ~/ 8,
      window ~/ 8 > legacyKeep ? window ~/ 8 : legacyKeep);
}

void main(List<String> args) {
  if (args.isEmpty || !File(args.first).existsSync()) {
    stderr.writeln(
      'usage: dart bench/compaction_trigger_sim.dart <session.jsonl> '
      '[--window N]...',
    );
    exit(2);
  }
  final windows = <int>[];
  for (var i = 1; i < args.length - 1; i++) {
    if (args[i] == '--window') windows.add(int.parse(args[i + 1]));
  }
  if (windows.isEmpty) windows.addAll([128000, 200000, 400000]);

  final observed = <int>[];
  for (final line in File(args.first).readAsLinesSync()) {
    if (line.trim().isEmpty) continue;
    Object? record;
    try {
      record = jsonDecode(line);
    } on FormatException {
      continue;
    }
    if (record is! Map || record['type'] != 'message') continue;
    final message = record['message'];
    if (message is! Map) continue;
    final usage = message['usage'];
    if (usage is! Map) continue;
    final input = (usage['input'] as num?)?.toInt() ?? 0;
    final cacheRead = (usage['cacheRead'] as num?)?.toInt() ?? 0;
    final size = input + cacheRead;
    if (size > 0) observed.add(size);
  }
  if (observed.length < 2) {
    stderr.writeln('no usable usage observations in ${args.first}');
    exit(2);
  }
  final maxObserved = observed.reduce((a, b) => a > b ? a : b);
  stderr.writeln(
    'recorded curve: ${observed.length} requests, '
    'observed context ${observed.first} → $maxObserved tokens',
  );

  for (final window in windows) {
    // The legacy curve (CompactionSettings.forWindow): reserve =
    // min(65536, max(window ~/ 16, min(16384, max(1024, window ~/ 4)))),
    // with the degenerate guards.
    var legacyReserve = window ~/ 16;
    final flat = (window ~/ 4).clamp(1024, 16384);
    if (legacyReserve < flat) legacyReserve = flat;
    if (legacyReserve > 65536) legacyReserve = 65536;
    if (legacyReserve >= window ~/ 2) legacyReserve = (window ~/ 4) >= 128
        ? window ~/ 4
        : 128;
    var legacyKeepRecent = window ~/ 8;
    final legacyFlatKeep = (window ~/ 2).clamp(2048, 20000);
    if (legacyKeepRecent < legacyFlatKeep) {
      legacyKeepRecent = legacyFlatKeep;
    }
    if (legacyKeepRecent > 131072) legacyKeepRecent = 131072;
    if (legacyKeepRecent >= window) legacyKeepRecent = (window ~/ 2) >= 256
        ? window ~/ 2
        : 256;

    stdout.writeln('');
    stdout.writeln(
      'window $window — legacy trigger ${window - legacyReserve} '
      '(${(100 * (window - legacyReserve) / window).toStringAsFixed(2)}%), '
      'keep $legacyKeepRecent',
    );
    for (final policy in _policies) {
      final ratio = _ratios[policy]!;
      final trigger =
          policy == 'legacy' ? window - legacyReserve : (window * ratio).floor();
      final keep =
          policy == 'legacy' ? legacyKeepRecent : legacyKeepRecent;
      var context = 0;
      var fires = 0;
      int? firstFire;
      var previous = observed.first;
      context = previous;
      if (context > trigger) {
        fires++;
        firstFire = context;
        context = keep;
      }
      for (final size in observed.skip(1)) {
        final delta = size - previous;
        previous = size;
        context += delta;
        if (context > trigger) {
          fires++;
          firstFire ??= context;
          context = keep;
        }
      }
      stdout.writeln(
        '  $policy: trigger $trigger, first fire at '
        '${firstFire ?? '— (never)'} (${firstFire == null ? '0.00' : (100 * firstFire / window).toStringAsFixed(2)}%), '
        'fires over the curve: $fires',
      );
    }
  }
}

