import json, glob, collections
hit=collections.defaultdict(set); miss=collections.defaultdict(set)
for p in glob.glob('coverage/test/compaction/*.vm.json'):
    d=json.load(open(p))
    cov=d['coverage']
    for entry in cov:
        sf=entry.get('source') or entry.get('sourceFile') or entry.get('path')
        if not sf or ('/tuning.dart' not in sf and '/host_wiring.dart' not in sf): continue
        key='tuning.dart' if '/tuning.dart' in sf else 'host_wiring.dart'
        for start,end,hits in entry.get('hits',[]):
            if hits>0:
                for l in range(start,end+1): hit[key].add(l)
            else:
                for l in range(start,end+1): miss[key].add(l)
for k in ('tuning.dart','host_wiring.dart'):
    m=miss[k]-hit[k]; h=hit[k]
    total=len(h|m)
    print(k, f'{len(h)}/{total} covered = {100*len(h)/total if total else 100:.1f}%', 'uncovered:', sorted(m)[:20])
EOF

